-- Generated by Supabase CLI 3.1.0; numbered to the repository convention.
-- Guarded service-only entry points. The private implementation has no API grants.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT table_name,column_name,data_type FROM information_schema.columns
 WHERE table_schema IN ('public','auth') AND table_name IN ('cfc_league_runtime','cfc_asset_ownership',
 'cfc_runtime_commands','cfc_draft_slots','league_memberships','sessions','users','draft_state','draft_log',
 'trade_offers','trade_threads','cfc_pending_trade_overlays','rookie_prospects','slp_raw_players_catalog')
 ORDER BY table_name,ordinal_position;
CREATE SCHEMA IF NOT EXISTS cfc_runtime_private;
REVOKE ALL ON SCHEMA cfc_runtime_private FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION cfc_runtime_private.authorize(p_league text,p_actor uuid,p_session uuid)
RETURNS public.league_memberships LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships;
BEGIN
 IF p_actor IS NULL OR p_session IS NULL OR NOT public.is_auth_session_active(p_session,p_actor) THEN
  RAISE SQLSTATE 'PT401' USING MESSAGE='session_inactive';
 END IF;
 -- Serialize revocation/account disable with the privileged action, not just a stale JWT.
 PERFORM 1 FROM auth.sessions s JOIN auth.users u ON u.id=s.user_id
 WHERE s.id=p_session AND s.user_id=p_actor AND (s.not_after IS NULL OR s.not_after>now())
 AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=now()) FOR SHARE OF s,u;
 IF NOT FOUND THEN RAISE SQLSTATE 'PT401' USING MESSAGE='session_inactive'; END IF;
 SELECT * INTO m FROM public.league_memberships WHERE league_id=p_league AND user_id=p_actor FOR SHARE;
 IF NOT FOUND THEN RAISE SQLSTATE 'PT403' USING MESSAGE='membership_required'; END IF;
 RETURN m;
END $$;
CREATE OR REPLACE FUNCTION cfc_runtime_private.refresh(p_league text,p_actor uuid,p_request uuid,p_expected bigint,p_snapshot jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE replay jsonb; r public.cfc_league_runtime; d public.draft_state; rosters text[];
 season integer; teams integer; rounds integer; seconds integer; observed timestamptz; incoming record; l record; k text;
 actual record; metadata jsonb;
BEGIN
 replay:=cfc_runtime_private.begin_command(p_league,p_actor,p_request,p_expected,'refresh',p_snapshot,true);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 SELECT * INTO r FROM public.cfc_league_runtime WHERE league_id=p_league;
 IF jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object' OR jsonb_typeof(p_snapshot->'assets') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_snapshot->'slots') IS DISTINCT FROM 'array' OR jsonb_typeof(p_snapshot->'roster_ids') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_snapshot->'assets')>20000 THEN RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_snapshot'; END IF;
 BEGIN
  season:=(p_snapshot->>'draft_season')::integer; teams:=(p_snapshot->>'team_count')::integer;
  rounds:=(p_snapshot->>'round_count')::integer; seconds:=(p_snapshot->>'pick_seconds')::integer;
  observed:=(p_snapshot->>'observed_at')::timestamptz;
 EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_snapshot_config'; END;
 IF season IS NULL OR season NOT BETWEEN 2000 AND 2200 OR teams IS NULL OR teams NOT BETWEEN 2 AND 64
 OR rounds IS NULL OR rounds NOT BETWEEN 1 AND 64 OR seconds IS NULL OR seconds NOT BETWEEN 10 AND 86400
 OR observed IS NULL OR observed>clock_timestamp()+interval '5 minutes' THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_snapshot_config'; END IF;
 IF r.source_observed_at IS NOT NULL AND observed<=r.source_observed_at THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='stale_source_snapshot'; END IF;
 SELECT array_agg(value ORDER BY value) INTO rosters FROM jsonb_array_elements_text(p_snapshot->'roster_ids');
 IF cardinality(rosters)<>teams OR (SELECT count(DISTINCT x) FROM unnest(rosters)x)<>teams
 OR EXISTS(SELECT 1 FROM unnest(rosters)x WHERE x IS NULL OR x !~ '^[A-Za-z0-9_-]{1,64}$') THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='incomplete_roster_snapshot'; END IF;
 IF r.initialized_at IS NOT NULL AND r.roster_ids<>rosters THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='roster_configuration_changed'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(p_snapshot->'assets') AS x(asset_key text,asset_kind text,owner_roster_id text,consumed boolean)
  WHERE x.asset_key IS NULL OR x.asset_kind IS NULL OR x.consumed IS NULL
  OR x.asset_kind NOT IN ('player','pick') OR (x.owner_roster_id IS NOT NULL AND NOT x.owner_roster_id=ANY(rosters))
  OR (x.asset_kind='player' AND (x.asset_key !~ '^player:[A-Za-z0-9_-]{1,64}$' OR x.consumed))
  OR (x.asset_kind='pick' AND x.asset_key !~ '^pick:[0-9]{4}-[1-9][0-9]*-[A-Za-z0-9_-]+$'))
 OR (SELECT count(*)<>count(DISTINCT x->>'asset_key') FROM jsonb_array_elements(p_snapshot->'assets')x) THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_snapshot_assets'; END IF;
 IF jsonb_array_length(p_snapshot->'slots')<>teams*rounds OR EXISTS(
  SELECT 1 FROM jsonb_to_recordset(p_snapshot->'slots')s(pick_index integer,asset_key text,round integer,slot integer)
  WHERE s.pick_index IS NULL OR s.pick_index<0 OR s.pick_index>=teams*rounds
   OR s.round IS DISTINCT FROM (s.pick_index/teams+1) OR s.slot IS DISTINCT FROM (s.pick_index%teams+1)
   OR split_part(s.asset_key,':',1)<>'pick' OR split_part(split_part(s.asset_key,':',2),'-',1)<>season::text
   OR split_part(split_part(s.asset_key,':',2),'-',2)<>s.round::text
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_snapshot->'assets')a WHERE a->>'asset_key'=s.asset_key AND a->>'asset_kind'='pick'))
 OR (SELECT count(*)<>count(DISTINCT x->>'pick_index') OR count(*)<>count(DISTINCT x->>'asset_key')
     FROM jsonb_array_elements(p_snapshot->'slots')x) THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_draft_slots'; END IF;
 IF EXISTS(SELECT 1 FROM public.cfc_draft_slots old JOIN jsonb_to_recordset(p_snapshot->'slots')s
  (pick_index integer,asset_key text,round integer,slot integer) ON old.pick_index=s.pick_index
  WHERE old.league_id=p_league AND old.draft_season=season AND (old.asset_key<>s.asset_key OR old.round<>s.round OR old.slot<>s.slot)) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='draft_slot_identity_changed'; END IF;
 SELECT * INTO d FROM public.draft_state WHERE league_id=p_league FOR UPDATE;
 IF FOUND AND d.draft_season IS NOT NULL AND (d.draft_season<>season OR d.team_count<>teams OR d.round_count<>rounds OR d.pick_seconds<>seconds)
 AND (d.status NOT IN ('not_started','complete','completed') OR EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league AND pending_local)) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='active_draft_configuration_changed'; END IF;
 IF r.initialized_at IS NULL AND EXISTS(SELECT 1 FROM public.cfc_pending_trade_overlays WHERE league_id=p_league AND accepted_at IS NOT NULL AND reconciled_at IS NULL) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='legacy_trades_require_reconciliation'; END IF;
 -- Only complete roster snapshots may turn omitted players into source-unowned.
 FOR incoming IN SELECT x.asset_key,x.asset_kind,x.owner_roster_id,x.consumed
  FROM jsonb_to_recordset(p_snapshot->'assets')x(asset_key text,asset_kind text,owner_roster_id text,consumed boolean)
  UNION ALL SELECT old.asset_key,old.asset_kind,NULL::text,false FROM public.cfc_asset_ownership old
   WHERE old.league_id=p_league AND old.asset_kind='player' AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_snapshot->'assets')x WHERE x->>'asset_key'=old.asset_key)
 LOOP
  INSERT INTO public.cfc_asset_ownership AS old(league_id,asset_key,asset_kind,owner_roster_id,consumed,
   source_owner_roster_id,source_consumed,last_mutation_revision)
  VALUES(p_league,incoming.asset_key,incoming.asset_kind,incoming.owner_roster_id,incoming.consumed,incoming.owner_roster_id,incoming.consumed,r.revision+1)
  ON CONFLICT(league_id,asset_key) DO UPDATE SET
   source_owner_roster_id=excluded.owner_roster_id,source_consumed=excluded.consumed,
   owner_roster_id=CASE WHEN old.pending_local THEN old.owner_roster_id ELSE excluded.owner_roster_id END,
   consumed=CASE WHEN old.pending_local THEN old.consumed ELSE excluded.consumed END,
   pending_local=old.pending_local AND (old.owner_roster_id IS DISTINCT FROM excluded.owner_roster_id OR old.consumed<>excluded.consumed),
   last_mutation_revision=CASE WHEN NOT old.pending_local AND
    (old.owner_roster_id IS DISTINCT FROM excluded.owner_roster_id OR old.consumed<>excluded.consumed)
    THEN r.revision+1 ELSE old.last_mutation_revision END,
   updated_at=now();
 END LOOP;
 INSERT INTO public.cfc_draft_slots(league_id,draft_season,pick_index,asset_key,round,slot)
 SELECT p_league,season,s.pick_index,s.asset_key,s.round,s.slot
 FROM jsonb_to_recordset(p_snapshot->'slots')s(pick_index integer,asset_key text,round integer,slot integer)
 ON CONFLICT(league_id,draft_season,pick_index) DO NOTHING;
 -- Actual provider results are history, not current roster ownership. A player
 -- may already have been traded/dropped after selection; retain snapshot owners.
 IF p_snapshot ? 'actual_picks' AND jsonb_typeof(p_snapshot->'actual_picks') IS DISTINCT FROM 'array' THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_actual_results'; END IF;
 IF (SELECT count(*)<>count(DISTINCT x->>'pick_index') OR count(*)<>count(DISTINCT x->>'player_id')
  FROM jsonb_array_elements(coalesce(p_snapshot->'actual_picks','[]'::jsonb))x) THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='duplicate_actual_results'; END IF;
 FOR actual IN SELECT * FROM jsonb_to_recordset(coalesce(p_snapshot->'actual_picks','[]'::jsonb))
  AS x(pick_index integer,player_id text,roster_id text,submitted_at timestamptz) LOOP
  SELECT asset_key INTO k FROM public.cfc_draft_slots WHERE league_id=p_league AND draft_season=season AND pick_index=actual.pick_index;
  IF k IS NULL OR actual.player_id IS NULL OR actual.roster_id IS NULL OR NOT actual.roster_id=ANY(rosters)
   OR NOT EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league AND asset_key=k AND source_consumed) THEN
   RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_actual_results'; END IF;
  IF EXISTS(SELECT 1 FROM public.draft_log WHERE league_id=p_league AND draft_season=season AND pick_index=actual.pick_index
   AND player_id IS NOT NULL AND (player_id<>actual.player_id OR roster_id IS DISTINCT FROM actual.roster_id)) THEN
   RAISE SQLSTATE 'PT409' USING MESSAGE='actual_result_conflict'; END IF;
  metadata:=cfc_runtime_private.player_metadata(actual.player_id);
  INSERT INTO public.draft_log(league_id,draft_season,pick_index,pick_number,team_count,roster_id,player_id,player_name,
   positions,nfl_team,submitted_at,announced_at,is_announced,is_skip,runtime_revision)
  VALUES(p_league,season,actual.pick_index,(actual.pick_index/teams+1)::text||'.'||lpad((actual.pick_index%teams+1)::text,2,'0'),
   teams,actual.roster_id,actual.player_id,metadata->>'name',jsonb_build_array(metadata->>'position'),metadata->>'team',
   actual.submitted_at,NULL,true,false,r.revision+1)
  ON CONFLICT(league_id,draft_season,pick_index) DO UPDATE SET
   roster_id=excluded.roster_id,player_id=excluded.player_id,player_name=excluded.player_name,positions=excluded.positions,nfl_team=excluded.nfl_team,
   is_skip=false,is_announced=CASE WHEN public.draft_log.is_skip THEN true ELSE public.draft_log.is_announced END;
  INSERT INTO public.cfc_asset_ownership(league_id,asset_key,asset_kind,owner_roster_id,draft_season,draft_pick_index,last_mutation_revision)
  VALUES(p_league,'player:'||actual.player_id,'player',NULL,season,actual.pick_index,r.revision+1)
  ON CONFLICT(league_id,asset_key) DO UPDATE SET draft_season=excluded.draft_season,draft_pick_index=excluded.draft_pick_index;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.cfc_draft_slots slot JOIN public.cfc_asset_ownership own
   ON own.league_id=slot.league_id AND own.asset_key=slot.asset_key
  WHERE slot.league_id=p_league AND slot.draft_season=season AND own.source_consumed AND NOT EXISTS(
   SELECT 1 FROM public.draft_log log WHERE log.league_id=p_league AND log.draft_season=season AND log.pick_index=slot.pick_index AND log.player_id IS NOT NULL)) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='actual_results_required'; END IF;
 -- Preserve accepted legacy draft selections when the first provider snapshot lags.
 IF r.initialized_at IS NULL THEN
  FOR l IN SELECT * FROM public.draft_log WHERE league_id=p_league AND draft_season=season AND player_id IS NOT NULL AND NOT is_skip LOOP
   SELECT asset_key INTO k FROM public.cfc_draft_slots WHERE league_id=p_league AND draft_season=season AND pick_index=l.pick_index;
   IF k IS NULL OR NOT l.roster_id=ANY(rosters) THEN RAISE SQLSTATE 'PT409' USING MESSAGE='legacy_draft_requires_reconciliation'; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_snapshot->'actual_picks','[]'::jsonb))x
     WHERE (x->>'pick_index')::integer=l.pick_index AND x->>'player_id'=l.player_id) THEN
    CONTINUE;
   END IF;
   IF EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league AND asset_key='player:'||l.player_id
    AND owner_roster_id IS NOT NULL AND owner_roster_id<>l.roster_id) THEN
    RAISE SQLSTATE 'PT409' USING MESSAGE='legacy_draft_ownership_conflict'; END IF;
   INSERT INTO public.cfc_asset_ownership AS old(league_id,asset_key,asset_kind,owner_roster_id,pending_local,last_mutation_revision,draft_season,draft_pick_index)
   VALUES(p_league,'player:'||l.player_id,'player',l.roster_id,true,r.revision+1,season,l.pick_index)
   ON CONFLICT(league_id,asset_key) DO UPDATE SET owner_roster_id=excluded.owner_roster_id,
    pending_local=old.source_owner_roster_id IS DISTINCT FROM excluded.owner_roster_id,
    draft_season=excluded.draft_season,draft_pick_index=excluded.draft_pick_index;
   UPDATE public.cfc_asset_ownership SET consumed=true,pending_local=NOT source_consumed,last_mutation_revision=r.revision+1
    WHERE league_id=p_league AND asset_key=k;
   UPDATE public.draft_log SET runtime_revision=r.revision+1 WHERE league_id=p_league AND draft_season=season AND pick_index=l.pick_index;
  END LOOP;
 END IF;
 INSERT INTO public.draft_state(league_id,draft_season,team_count,round_count,pick_seconds,seconds_remaining,current_pick_index)
 VALUES(p_league,season,teams,rounds,seconds,seconds,0)
 ON CONFLICT(league_id) DO UPDATE SET draft_season=excluded.draft_season,team_count=excluded.team_count,
 round_count=excluded.round_count,pick_seconds=excluded.pick_seconds,
 status=CASE WHEN public.draft_state.draft_season IS DISTINCT FROM excluded.draft_season THEN 'not_started' ELSE public.draft_state.status END,
 current_pick_index=CASE WHEN public.draft_state.draft_season IS DISTINCT FROM excluded.draft_season THEN 0 ELSE coalesce(public.draft_state.current_pick_index,0) END;
 -- Bootstrap a draft already in progress on the provider at its first empty slot.
 IF d.league_id IS NULL OR d.draft_season IS DISTINCT FROM season OR (d.status='not_started' AND d.clock_started_at IS NULL) THEN
  UPDATE public.draft_state SET current_pick_index=coalesce((SELECT min(slot.pick_index) FROM public.cfc_draft_slots slot
    WHERE slot.league_id=p_league AND slot.draft_season=season AND NOT EXISTS(SELECT 1 FROM public.draft_log log
    WHERE log.league_id=p_league AND log.draft_season=season AND log.pick_index=slot.pick_index AND log.player_id IS NOT NULL)),teams*rounds)
   WHERE league_id=p_league;
  UPDATE public.draft_state SET status=CASE WHEN current_pick_index>=teams*rounds THEN 'completed' ELSE status END
   WHERE league_id=p_league;
 END IF;
 IF (SELECT count(*) FROM public.draft_log WHERE league_id=p_league AND draft_season=season
   AND pick_index>=0 AND pick_index<teams*rounds AND player_id IS NOT NULL AND is_announced)=teams*rounds THEN
  UPDATE public.draft_state SET status='completed',current_pick_index=teams*rounds,seconds_remaining=0,
   clock_started_at=NULL,pick_submitted=false,pick_announced_at=NULL WHERE league_id=p_league;
 END IF;
 UPDATE public.cfc_league_runtime SET source_revision=source_revision+1,source_observed_at=observed,
 initialized_at=coalesce(initialized_at,now()),roster_ids=rosters WHERE league_id=p_league;
 UPDATE public.cfc_pending_trade_overlays o SET reconciled_at=now() WHERE o.league_id=p_league AND o.accepted_at IS NOT NULL AND o.reconciled_at IS NULL
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(o.assets_from||o.assets_to)x JOIN public.cfc_asset_ownership a
  ON a.league_id=o.league_id AND a.asset_key=x->>'key' WHERE a.pending_local);
 RETURN cfc_runtime_private.finish_command(p_league,p_actor,p_request,'refresh',p_snapshot,jsonb_build_object(
  'source_revision',r.source_revision+1,'pending_assets',(SELECT count(*) FROM public.cfc_asset_ownership WHERE league_id=p_league AND pending_local),
  'divergent_assets',(SELECT count(*) FROM public.cfc_asset_ownership WHERE league_id=p_league AND pending_local
   AND (owner_roster_id IS DISTINCT FROM source_owner_roster_id OR consumed<>source_consumed))));
END $$;

CREATE OR REPLACE FUNCTION public.cfc_refresh_runtime_snapshot(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_request_id uuid,p_expected_revision bigint,p_snapshot jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 PERFORM cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('cfc-runtime:'||p_league_id,0));
 INSERT INTO public.cfc_league_runtime(league_id) VALUES(p_league_id) ON CONFLICT(league_id) DO NOTHING;
 RETURN cfc_runtime_private.refresh(p_league_id,p_actor_user_id,p_request_id,p_expected_revision,p_snapshot);
END $$;
CREATE OR REPLACE FUNCTION public.cfc_refresh_runtime_snapshot_system(p_league_id text,p_request_id uuid,p_expected_revision bigint,p_snapshot jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 RETURN cfc_runtime_private.refresh(p_league_id,'00000000-0000-0000-0000-000000000000',p_request_id,p_expected_revision,p_snapshot);
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.begin_command(p_league text,p_actor uuid,p_request uuid,
 p_expected bigint,p_operation text,p_payload jsonb,p_refresh boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.cfc_league_runtime; c public.cfc_runtime_commands; h text;
BEGIN
 IF p_request IS NULL OR p_expected IS NULL OR p_expected<0 OR length(coalesce(p_league,'')) NOT BETWEEN 1 AND 100 THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_command'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('cfc-runtime:'||p_league,0));
 SELECT * INTO r FROM public.cfc_league_runtime WHERE league_id=p_league FOR UPDATE;
 IF NOT FOUND THEN RAISE SQLSTATE 'PT503' USING MESSAGE='snapshot_required'; END IF;
 h:=encode(sha256(convert_to(jsonb_build_object('operation',p_operation,'payload',p_payload)::text,'UTF8')),'hex');
 SELECT * INTO c FROM public.cfc_runtime_commands WHERE league_id=p_league AND actor_user_id=p_actor AND request_id=p_request;
 IF FOUND THEN
  IF c.payload_hash<>h THEN RAISE SQLSTATE 'PT409' USING MESSAGE='idempotency_payload_mismatch'; END IF;
  RETURN c.result||'{"replayed":true}'::jsonb;
 END IF;
 IF r.revision<>p_expected THEN RAISE SQLSTATE 'PT409' USING MESSAGE='revision_conflict'; END IF;
 IF NOT p_refresh AND r.initialized_at IS NULL THEN RAISE SQLSTATE 'PT503' USING MESSAGE='snapshot_required'; END IF;
 IF NOT p_refresh AND NOT r.writes_enabled THEN RAISE SQLSTATE 'PT503' USING MESSAGE='runtime_paused'; END IF;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.finish_command(p_league text,p_actor uuid,p_request uuid,
 p_operation text,p_payload jsonb,p_result jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v bigint; r jsonb;
BEGIN
 UPDATE public.cfc_league_runtime SET revision=revision+1 WHERE league_id=p_league RETURNING revision INTO v;
 r:=p_result||jsonb_build_object('ok',true,'revision',v,'replayed',false);
 INSERT INTO public.cfc_runtime_commands(league_id,actor_user_id,request_id,operation,payload_hash,result)
 VALUES(p_league,p_actor,p_request,p_operation,
 encode(sha256(convert_to(jsonb_build_object('operation',p_operation,'payload',p_payload)::text,'UTF8')),'hex'),r);
 IF p_actor<>'00000000-0000-0000-0000-000000000000'::uuid THEN
  INSERT INTO public.security_audit_log(actor_user_id,league_id,target_type,target_id,action,outcome,change_summary)
  VALUES(p_actor,p_league,'team_ownership',p_request::text,p_operation,'success',jsonb_build_object('revision',v));
 END IF;
 RETURN r;
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.snapshot(p_league text,p_roster text DEFAULT NULL,p_commissioner boolean DEFAULT false)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce((SELECT jsonb_build_object(
 'initialized',r.initialized_at IS NOT NULL,'writes_enabled',r.writes_enabled,'revision',r.revision,
 'source_revision',r.source_revision,'source_observed_at',r.source_observed_at,'roster_ids',r.roster_ids,
 'assets',coalesce((SELECT jsonb_agg(to_jsonb(a)-'source_owner_roster_id'-'source_consumed' ORDER BY a.asset_key)
  FROM public.cfc_asset_ownership a WHERE a.league_id=r.league_id AND NOT EXISTS(
   SELECT 1 FROM public.draft_log l WHERE l.league_id=a.league_id AND l.draft_season=a.draft_season
   AND l.pick_index=a.draft_pick_index AND NOT l.is_announced
   AND NOT (p_commissioner OR coalesce(l.roster_id=p_roster,false)))),'[]'::jsonb),
 'slots',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.draft_season,s.pick_index)
  FROM public.cfc_draft_slots s WHERE s.league_id=r.league_id),'[]'::jsonb),
 'announced_picks',coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.pick_index)
  FROM public.draft_log l JOIN public.draft_state d ON d.league_id=l.league_id AND d.draft_season=l.draft_season
  WHERE l.league_id=r.league_id AND l.is_announced),'[]'::jsonb),
 'draft_state',(SELECT to_jsonb(d) FROM public.draft_state d WHERE d.league_id=r.league_id))
 FROM public.cfc_league_runtime r WHERE r.league_id=p_league),
 jsonb_build_object('initialized',false,'writes_enabled',false,'revision',0,'source_revision',0,
 'source_observed_at',null,'roster_ids','[]'::jsonb,'assets','[]'::jsonb,'slots','[]'::jsonb,
 'announced_picks','[]'::jsonb,'draft_state',null));
$$;
CREATE OR REPLACE FUNCTION public.cfc_get_league_runtime_public(p_league_id text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT cfc_runtime_private.snapshot(p_league_id);
$$;
CREATE OR REPLACE FUNCTION public.cfc_get_league_runtime(p_league_id text,p_actor_user_id uuid,p_session_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 RETURN cfc_runtime_private.snapshot(p_league_id,m.roster_id,m.role IN ('commissioner','admin'));
END $$;

CREATE OR REPLACE FUNCTION public.cfc_get_draft_log(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_draft_season integer DEFAULT NULL,p_include_unannounced boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; result jsonb;
BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 IF coalesce(p_include_unannounced,false) AND m.role NOT IN ('commissioner','admin') THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='commissioner_required'; END IF;
 IF p_draft_season IS NOT NULL AND p_draft_season NOT BETWEEN 1900 AND 2200 THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_draft_season'; END IF;
 -- One statement supplies the revision, current-season fallback and visible rows.
 -- Do not replace this with separate REST reads: a reveal may commit between them.
 SELECT jsonb_build_object(
  'revision',coalesce((SELECT r.revision FROM public.cfc_league_runtime r WHERE r.league_id=p_league_id),0),
  'data',coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.pick_index) FROM public.draft_log l
   WHERE l.league_id=p_league_id
    AND l.draft_season=coalesce(p_draft_season,(SELECT d.draft_season FROM public.draft_state d WHERE d.league_id=p_league_id))
    AND (l.is_announced OR coalesce(p_include_unannounced,false))),'[]'::jsonb)) INTO result;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.validate_trade_assets(p_league text,p_from text,p_to text,p_assets_from jsonb,p_assets_to jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_from IS NULL OR p_to IS NULL OR p_from=p_to
 OR NOT EXISTS(SELECT 1 FROM public.cfc_league_runtime WHERE league_id=p_league AND p_from=ANY(roster_ids) AND p_to=ANY(roster_ids))
 OR jsonb_typeof(p_assets_from) IS DISTINCT FROM 'array' OR jsonb_typeof(p_assets_to) IS DISTINCT FROM 'array' THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_trade'; END IF;
 IF jsonb_array_length(p_assets_from) NOT BETWEEN 1 AND 100 OR jsonb_array_length(p_assets_to) NOT BETWEEN 1 AND 100
 OR octet_length((p_assets_from||p_assets_to)::text)>100000
 OR (SELECT count(*)<>count(DISTINCT x->>'key') FROM jsonb_array_elements(p_assets_from||p_assets_to)x)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_assets_from||p_assets_to)x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
   OR x->>'type' IS NULL OR x->>'type' NOT IN ('player','pick') OR length(coalesce(x->>'label','')) NOT BETWEEN 1 AND 200) THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_trade_assets'; END IF;
 IF EXISTS(SELECT 1 FROM (
  SELECT x->>'key' k,x->>'type' kind,p_from owner FROM jsonb_array_elements(p_assets_from)x
  UNION ALL SELECT x->>'key',x->>'type',p_to FROM jsonb_array_elements(p_assets_to)x
 ) x LEFT JOIN public.cfc_asset_ownership a ON a.league_id=p_league AND a.asset_key=x.k
 WHERE a.asset_key IS NULL OR a.asset_kind<>x.kind OR a.owner_roster_id IS DISTINCT FROM x.owner OR a.consumed
 OR EXISTS(SELECT 1 FROM public.draft_log l WHERE l.league_id=a.league_id AND l.draft_season=a.draft_season
  AND l.pick_index=a.draft_pick_index AND NOT l.is_announced)) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='ownership_changed'; END IF;
END $$;

CREATE OR REPLACE FUNCTION public.cfc_create_trade_offer(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_request_id uuid,p_expected_revision bigint,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; replay jsonb; parent public.trade_offers; tid uuid; oid uuid; intent jsonb;
 f text:=p_payload->>'from_team_id'; t text:=p_payload->>'to_team_id'; parent_id uuid;
BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 IF jsonb_typeof(p_payload->'assets_from') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'assets_to') IS DISTINCT FROM 'array' THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_trade_assets'; END IF;
 intent:=jsonb_build_object('from_team_id',f,'to_team_id',t,'parent_offer_id',p_payload->>'parent_offer_id',
  'assets_from',(SELECT jsonb_agg(x->>'key' ORDER BY x->>'key') FROM jsonb_array_elements(p_payload->'assets_from')x),
  'assets_to',(SELECT jsonb_agg(x->>'key' ORDER BY x->>'key') FROM jsonb_array_elements(p_payload->'assets_to')x));
 replay:=cfc_runtime_private.begin_command(p_league_id,p_actor_user_id,p_request_id,p_expected_revision,'create_trade',intent);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 IF m.roster_id IS DISTINCT FROM f THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='roster_forbidden'; END IF;
 PERFORM cfc_runtime_private.validate_trade_assets(p_league_id,f,t,p_payload->'assets_from',p_payload->'assets_to');
 IF length(coalesce(p_payload->>'grade_label','Fair'))>120 OR octet_length(coalesce(p_payload->'asset_summary','{}'::jsonb)::text)>100000 THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_trade_metadata'; END IF;
 BEGIN parent_id:=nullif(p_payload->>'parent_offer_id','')::uuid;
 EXCEPTION WHEN invalid_text_representation THEN RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_parent_offer'; END;
 IF parent_id IS NOT NULL THEN
  SELECT * INTO parent FROM public.trade_offers WHERE league_id=p_league_id AND id=parent_id FOR UPDATE;
  IF NOT FOUND THEN RAISE SQLSTATE 'PT404' USING MESSAGE='offer_not_found'; END IF;
  IF parent.status<>'pending' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='offer_not_pending'; END IF;
  IF parent.to_team_id<>f OR parent.from_team_id<>t THEN RAISE SQLSTATE 'PT403' USING MESSAGE='counterparty_mismatch'; END IF;
  tid:=parent.thread_id;
  UPDATE public.trade_offers SET status='countered',updated_at=now() WHERE id=parent_id AND league_id=p_league_id;
 ELSE
  INSERT INTO public.trade_threads(league_id,team_a_id,team_b_id,created_by_team_id,last_offer_at)
  VALUES(p_league_id,least(f,t),greatest(f,t),f,now()) RETURNING id INTO tid;
 END IF;
 INSERT INTO public.trade_offers(league_id,from_team_id,to_team_id,assets_from,assets_to,from_value,to_value,
  from_base_value,to_base_value,grade_label,parent_offer_id,thread_id,asset_summary)
 VALUES(p_league_id,f,t,p_payload->'assets_from',p_payload->'assets_to',
  (p_payload->>'from_value')::integer,(p_payload->>'to_value')::integer,
  (p_payload->>'from_base_value')::integer,(p_payload->>'to_base_value')::integer,
  coalesce(p_payload->>'grade_label','Fair'),parent_id,tid,p_payload->'asset_summary') RETURNING id INTO oid;
 UPDATE public.trade_threads SET status='open',last_offer_at=now(),last_activity_at=now(),updated_at=now(),
  unread_by_team_a=unread_by_team_a+CASE WHEN team_a_id=t THEN 1 ELSE 0 END,
  unread_by_team_b=unread_by_team_b+CASE WHEN team_b_id=t THEN 1 ELSE 0 END WHERE league_id=p_league_id AND id=tid;
 RETURN cfc_runtime_private.finish_command(p_league_id,p_actor_user_id,p_request_id,'create_trade',intent,
  jsonb_build_object('id',oid,'thread_id',tid,'status','pending'));
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.player_metadata(p_player text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb; BEGIN
 IF p_player IS NULL OR p_player !~ '^[A-Za-z0-9_-]{1,64}$' THEN RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_player'; END IF;
 IF to_regclass('public.slp_raw_players_catalog') IS NOT NULL THEN
  EXECUTE 'SELECT jsonb_build_object(''name'',coalesce(full_name,concat_ws('' '',first_name,last_name),sleeper_player_id),''position'',position,''team'',team) FROM public.slp_raw_players_catalog WHERE sleeper_player_id=$1 AND sport=''nfl'' LIMIT 1'
  INTO result USING p_player;
 END IF;
 IF result IS NULL AND to_regclass('public.rookie_prospects') IS NOT NULL THEN
  EXECUTE 'SELECT jsonb_build_object(''name'',player_name,''position'',position,''team'',nfl_team) FROM public.rookie_prospects WHERE player_id=$1 LIMIT 1'
  INTO result USING p_player;
 END IF;
 IF result IS NULL THEN RAISE SQLSTATE 'PT404' USING MESSAGE='player_not_found'; END IF;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.cfc_submit_draft_pick(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_request_id uuid,p_expected_revision bigint,p_draft_season integer,p_pick_index integer,p_acting_roster_id text,p_player_id text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; replay jsonb; payload jsonb; d public.draft_state; s public.cfc_draft_slots;
 a public.cfc_asset_ownership; l public.draft_log; meta jsonb; late boolean; announce timestamptz;
BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 payload:=jsonb_build_object('draft_season',p_draft_season,'pick_index',p_pick_index,'acting_roster_id',p_acting_roster_id,'player_id',p_player_id);
 replay:=cfc_runtime_private.begin_command(p_league_id,p_actor_user_id,p_request_id,p_expected_revision,'submit_draft',payload);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 IF m.roster_id IS DISTINCT FROM p_acting_roster_id AND m.role NOT IN ('commissioner','admin') THEN RAISE SQLSTATE 'PT403' USING MESSAGE='roster_forbidden'; END IF;
 SELECT * INTO d FROM public.draft_state WHERE league_id=p_league_id FOR UPDATE;
 IF NOT FOUND OR d.draft_season IS DISTINCT FROM p_draft_season OR d.status NOT IN ('running','completed') THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='draft_not_running'; END IF;
 SELECT * INTO s FROM public.cfc_draft_slots WHERE league_id=p_league_id AND draft_season=p_draft_season AND pick_index=p_pick_index;
 IF NOT FOUND OR p_pick_index>d.current_pick_index THEN RAISE SQLSTATE 'PT409' USING MESSAGE='pick_not_available'; END IF;
 SELECT * INTO a FROM public.cfc_asset_ownership WHERE league_id=p_league_id AND asset_key=s.asset_key;
 IF a.consumed OR a.owner_roster_id IS DISTINCT FROM p_acting_roster_id THEN RAISE SQLSTATE 'PT409' USING MESSAGE='ownership_changed'; END IF;
 SELECT * INTO l FROM public.draft_log WHERE league_id=p_league_id AND draft_season=p_draft_season AND pick_index=p_pick_index;
 late:=p_pick_index<d.current_pick_index;
 IF (late AND (NOT FOUND OR NOT l.is_skip OR l.player_id IS NOT NULL)) OR (NOT late AND FOUND) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='pick_not_available'; END IF;
 IF NOT late AND (d.clock_started_at IS NULL OR clock_timestamp()>=d.clock_started_at+d.seconds_remaining*interval '1 second') THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='clock_expired'; END IF;
 IF EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league_id AND asset_key='player:'||p_player_id AND owner_roster_id IS NOT NULL)
 OR EXISTS(SELECT 1 FROM public.draft_log WHERE league_id=p_league_id AND draft_season=p_draft_season AND player_id=p_player_id) THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='player_unavailable'; END IF;
 meta:=cfc_runtime_private.player_metadata(p_player_id);
 announce:=CASE WHEN late THEN clock_timestamp() ELSE d.clock_started_at+d.seconds_remaining*interval '1 second' END;
 UPDATE public.cfc_asset_ownership SET consumed=true,pending_local=true,last_mutation_revision=p_expected_revision+1,updated_at=now()
 WHERE league_id=p_league_id AND asset_key=s.asset_key;
 INSERT INTO public.cfc_asset_ownership(league_id,asset_key,asset_kind,owner_roster_id,pending_local,last_mutation_revision,draft_season,draft_pick_index)
 VALUES(p_league_id,'player:'||p_player_id,'player',p_acting_roster_id,true,p_expected_revision+1,p_draft_season,p_pick_index)
 ON CONFLICT(league_id,asset_key) DO UPDATE SET owner_roster_id=excluded.owner_roster_id,pending_local=true,
 last_mutation_revision=excluded.last_mutation_revision,draft_season=excluded.draft_season,draft_pick_index=excluded.draft_pick_index,updated_at=now();
 INSERT INTO public.draft_log(league_id,draft_season,pick_index,pick_number,team_count,roster_id,player_id,player_name,positions,nfl_team,
  submitted_at,announced_at,is_announced,is_skip,runtime_revision)
 VALUES(p_league_id,p_draft_season,p_pick_index,s.round::text||'.'||lpad(s.slot::text,2,'0'),d.team_count,p_acting_roster_id,p_player_id,
  meta->>'name',CASE WHEN meta->>'position' IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(meta->>'position') END,meta->>'team',
  clock_timestamp(),announce,late,false,p_expected_revision+1)
 ON CONFLICT(league_id,draft_season,pick_index) DO UPDATE SET roster_id=excluded.roster_id,player_id=excluded.player_id,
 player_name=excluded.player_name,positions=excluded.positions,nfl_team=excluded.nfl_team,submitted_at=excluded.submitted_at,
 announced_at=excluded.announced_at,is_announced=excluded.is_announced,is_skip=false,runtime_revision=excluded.runtime_revision
 RETURNING * INTO l;
 IF NOT late THEN
  UPDATE public.draft_state SET pick_submitted=true,pick_announced_at=announce WHERE league_id=p_league_id RETURNING * INTO d;
 END IF;
 RETURN cfc_runtime_private.finish_command(p_league_id,p_actor_user_id,p_request_id,'submit_draft',payload,
  jsonb_build_object('data',to_jsonb(d),'pick',to_jsonb(l),'status','submitted'));
END $$;

CREATE OR REPLACE FUNCTION cfc_runtime_private.tick(p_league text,p_force boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE d public.draft_state; s public.cfc_draft_slots; l public.draft_log; deadline timestamptz;
 steps integer:=0; state text:='not_ready'; v_now timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO d FROM public.draft_state WHERE league_id=p_league FOR UPDATE;
 IF d.status='not_started' AND d.starts_at IS NOT NULL AND d.starts_at<=v_now THEN
  UPDATE public.draft_state SET status='running',clock_started_at=starts_at,seconds_remaining=pick_seconds
   WHERE league_id=p_league RETURNING * INTO d;
 END IF;
 WHILE d.status='running' AND steps<64 LOOP
  deadline:=d.clock_started_at+d.seconds_remaining*interval '1 second';
  IF deadline IS NULL OR (deadline>v_now AND NOT (p_force AND steps=0)) THEN EXIT; END IF;
  SELECT * INTO s FROM public.cfc_draft_slots WHERE league_id=p_league AND draft_season=d.draft_season AND pick_index=d.current_pick_index;
  IF NOT FOUND THEN RAISE SQLSTATE 'PT409' USING MESSAGE='draft_slot_missing'; END IF;
  SELECT * INTO l FROM public.draft_log WHERE league_id=p_league AND draft_season=d.draft_season AND pick_index=d.current_pick_index;
  IF FOUND AND NOT l.is_skip AND l.player_id IS NOT NULL THEN
   UPDATE public.draft_log SET is_announced=true,announced_at=v_now WHERE league_id=p_league AND draft_season=d.draft_season AND pick_index=d.current_pick_index;
   state:='announced';
  ELSE
   INSERT INTO public.draft_log(league_id,draft_season,pick_index,pick_number,team_count,roster_id,submitted_at,announced_at,is_announced,is_skip)
   SELECT p_league,d.draft_season,d.current_pick_index,s.round::text||'.'||lpad(s.slot::text,2,'0'),d.team_count,a.owner_roster_id,v_now,v_now,true,true
   FROM public.cfc_asset_ownership a WHERE a.league_id=p_league AND a.asset_key=s.asset_key
   ON CONFLICT(league_id,draft_season,pick_index) DO NOTHING;
   state:='skipped';
  END IF;
  steps:=steps+1;
  UPDATE public.draft_state SET current_pick_index=current_pick_index+1,pick_submitted=false,pick_announced_at=NULL,
   status=CASE WHEN current_pick_index+1>=team_count*round_count THEN 'completed' ELSE 'running' END,
   seconds_remaining=CASE WHEN current_pick_index+1>=team_count*round_count THEN 0 ELSE pick_seconds END,
   clock_started_at=CASE WHEN current_pick_index+1>=team_count*round_count THEN NULL
    WHEN p_force AND steps=1 THEN v_now ELSE deadline END
   WHERE league_id=p_league RETURNING * INTO d;
  IF d.status='completed' THEN state:='completed'; END IF;
 END LOOP;
 RETURN jsonb_build_object('data',to_jsonb(d),'status',state,'steps',steps);
END $$;

CREATE OR REPLACE FUNCTION public.cfc_draft_command(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_request_id uuid,p_expected_revision bigint,p_action text,p_options jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; replay jsonb; payload jsonb; d public.draft_state; l public.draft_log;
 s public.cfc_draft_slots; result jsonb; force boolean; remaining numeric; starts timestamptz; idx integer;
BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 payload:=jsonb_build_object('action',p_action,'options',coalesce(p_options,'{}'::jsonb));
 replay:=cfc_runtime_private.begin_command(p_league_id,p_actor_user_id,p_request_id,p_expected_revision,'draft_command',payload);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 IF p_action IS NULL OR p_action NOT IN ('start','pause','resume','advance','tick','undo','schedule') THEN
  RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_draft_action'; END IF;
 force:=coalesce((p_options->>'force')::boolean,false);
 IF (p_action<>'tick' OR force) AND m.role NOT IN ('commissioner','admin') THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='commissioner_required'; END IF;
 SELECT * INTO d FROM public.draft_state WHERE league_id=p_league_id FOR UPDATE;
 IF NOT FOUND THEN RAISE SQLSTATE 'PT503' USING MESSAGE='snapshot_required'; END IF;
 IF p_action IN ('tick','advance') THEN result:=cfc_runtime_private.tick(p_league_id,force);
 ELSIF p_action='start' THEN
  IF d.status<>'not_started' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='invalid_draft_transition'; END IF;
  UPDATE public.draft_state SET status='running',clock_started_at=clock_timestamp(),seconds_remaining=pick_seconds,starts_at=NULL
   WHERE league_id=p_league_id RETURNING * INTO d;
 ELSIF p_action='pause' THEN
  IF d.status<>'running' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='invalid_draft_transition'; END IF;
  remaining:=greatest(0,d.seconds_remaining-extract(epoch FROM clock_timestamp()-d.clock_started_at));
  UPDATE public.draft_state SET status='paused',seconds_remaining=remaining,clock_started_at=NULL,pick_announced_at=NULL
   WHERE league_id=p_league_id RETURNING * INTO d;
 ELSIF p_action='resume' THEN
  IF d.status<>'paused' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='invalid_draft_transition'; END IF;
  UPDATE public.draft_state SET status='running',clock_started_at=clock_timestamp(),
   pick_announced_at=CASE WHEN pick_submitted THEN clock_timestamp()+seconds_remaining*interval '1 second' ELSE NULL END
   WHERE league_id=p_league_id RETURNING * INTO d;
  UPDATE public.draft_log SET announced_at=d.pick_announced_at WHERE league_id=p_league_id AND draft_season=d.draft_season AND pick_index=d.current_pick_index AND NOT is_announced;
 ELSIF p_action='schedule' THEN
  IF d.status<>'not_started' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='invalid_draft_transition'; END IF;
  starts:=(p_options->>'starts_at')::timestamptz;
  IF starts IS NULL OR starts<=clock_timestamp() OR starts>clock_timestamp()+interval '1 year' THEN RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_schedule'; END IF;
  UPDATE public.draft_state SET starts_at=starts WHERE league_id=p_league_id RETURNING * INTO d;
 ELSIF p_action='undo' THEN
  idx:=(p_options->>'pick_index')::integer;
  IF idx IS NULL OR idx<0 OR idx NOT IN (d.current_pick_index,d.current_pick_index-1) THEN RAISE SQLSTATE 'PT409' USING MESSAGE='undo_not_latest'; END IF;
  IF EXISTS(SELECT 1 FROM public.draft_log WHERE league_id=p_league_id AND draft_season=d.draft_season AND pick_index>idx AND player_id IS NOT NULL) THEN
   RAISE SQLSTATE 'PT409' USING MESSAGE='undo_not_latest'; END IF;
  SELECT * INTO l FROM public.draft_log WHERE league_id=p_league_id AND draft_season=d.draft_season AND pick_index=idx;
  IF NOT FOUND THEN RAISE SQLSTATE 'PT404' USING MESSAGE='draft_pick_not_found'; END IF;
  SELECT * INTO s FROM public.cfc_draft_slots WHERE league_id=p_league_id AND draft_season=d.draft_season AND pick_index=idx;
  IF l.player_id IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league_id AND asset_key='player:'||l.player_id
    AND owner_roster_id=l.roster_id AND last_mutation_revision=l.runtime_revision AND source_owner_roster_id IS NULL)
   OR EXISTS(SELECT 1 FROM public.cfc_asset_ownership WHERE league_id=p_league_id AND asset_key=s.asset_key AND source_consumed) THEN
    RAISE SQLSTATE 'PT409' USING MESSAGE='undo_requires_reconciliation'; END IF;
   UPDATE public.cfc_asset_ownership SET owner_roster_id=NULL,pending_local=false,draft_season=NULL,draft_pick_index=NULL,
    last_mutation_revision=p_expected_revision+1,updated_at=now() WHERE league_id=p_league_id AND asset_key='player:'||l.player_id;
   UPDATE public.cfc_asset_ownership SET consumed=false,pending_local=owner_roster_id IS DISTINCT FROM source_owner_roster_id,
    last_mutation_revision=p_expected_revision+1,updated_at=now() WHERE league_id=p_league_id AND asset_key=s.asset_key;
  END IF;
  DELETE FROM public.draft_log WHERE league_id=p_league_id AND draft_season=d.draft_season AND pick_index=idx;
  UPDATE public.draft_state SET status='paused',current_pick_index=idx,seconds_remaining=pick_seconds,
   clock_started_at=NULL,pick_submitted=false,pick_announced_at=NULL WHERE league_id=p_league_id RETURNING * INTO d;
 END IF;
 RETURN cfc_runtime_private.finish_command(p_league_id,p_actor_user_id,p_request_id,'draft_command',payload,
  coalesce(result,jsonb_build_object('data',to_jsonb(d),'status',d.status,'steps',0)));
END $$;
CREATE OR REPLACE FUNCTION public.cfc_tick_due_draft(p_league_id text,p_request_id uuid,p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE replay jsonb; result jsonb; BEGIN
 replay:=cfc_runtime_private.begin_command(p_league_id,'00000000-0000-0000-0000-000000000000',p_request_id,p_expected_revision,'tick','{}'::jsonb);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 result:=cfc_runtime_private.tick(p_league_id,false);
 RETURN cfc_runtime_private.finish_command(p_league_id,'00000000-0000-0000-0000-000000000000',p_request_id,'tick','{}'::jsonb,result);
END $$;

CREATE OR REPLACE FUNCTION public.cfc_resolve_trade_offer(p_league_id text,p_actor_user_id uuid,p_session_id uuid,
 p_request_id uuid,p_expected_revision bigint,p_offer_id uuid,p_acting_roster_id text,p_status text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m public.league_memberships; replay jsonb; o public.trade_offers; payload jsonb;
BEGIN
 m:=cfc_runtime_private.authorize(p_league_id,p_actor_user_id,p_session_id);
 payload:=jsonb_build_object('offer_id',p_offer_id,'acting_roster_id',p_acting_roster_id,'status',p_status);
 replay:=cfc_runtime_private.begin_command(p_league_id,p_actor_user_id,p_request_id,p_expected_revision,'resolve_trade',payload);
 IF replay IS NOT NULL THEN RETURN replay; END IF;
 IF m.roster_id IS DISTINCT FROM p_acting_roster_id THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='roster_forbidden'; END IF;
 IF p_status IS NULL OR p_status NOT IN ('accepted','declined','withdrawn') THEN RAISE SQLSTATE 'PT400' USING MESSAGE='invalid_transition'; END IF;
 SELECT * INTO o FROM public.trade_offers WHERE league_id=p_league_id AND id=p_offer_id FOR UPDATE;
 IF NOT FOUND THEN RAISE SQLSTATE 'PT404' USING MESSAGE='offer_not_found'; END IF;
 IF o.status<>'pending' THEN RAISE SQLSTATE 'PT409' USING MESSAGE='offer_not_pending'; END IF;
 IF p_acting_roster_id IS DISTINCT FROM (CASE WHEN p_status='withdrawn' THEN o.from_team_id ELSE o.to_team_id END) THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='offer_action_forbidden'; END IF;
 IF p_status='accepted' THEN
  PERFORM cfc_runtime_private.validate_trade_assets(p_league_id,o.from_team_id,o.to_team_id,o.assets_from,o.assets_to);
  UPDATE public.cfc_asset_ownership a SET owner_roster_id=x.target,pending_local=true,
   last_mutation_revision=p_expected_revision+1,updated_at=now()
  FROM (SELECT v->>'key' k,o.to_team_id target FROM jsonb_array_elements(o.assets_from)v
   UNION ALL SELECT v->>'key',o.from_team_id FROM jsonb_array_elements(o.assets_to)v)x
  WHERE a.league_id=p_league_id AND a.asset_key=x.k;
  INSERT INTO public.cfc_pending_trade_overlays(offer_id,league_id,from_team_id,to_team_id,assets_from,assets_to,accepted_at)
  VALUES(o.id,p_league_id,o.from_team_id,o.to_team_id,o.assets_from,o.assets_to,now())
  ON CONFLICT(offer_id) DO UPDATE SET from_team_id=excluded.from_team_id,to_team_id=excluded.to_team_id,
   assets_from=excluded.assets_from,assets_to=excluded.assets_to,accepted_at=excluded.accepted_at,reconciled_at=NULL;
 END IF;
 UPDATE public.trade_offers SET status=p_status,updated_at=now() WHERE league_id=p_league_id AND id=o.id;
 UPDATE public.trade_threads SET status=p_status,last_activity_at=now(),updated_at=now() WHERE league_id=p_league_id AND id=o.thread_id;
 RETURN cfc_runtime_private.finish_command(p_league_id,p_actor_user_id,p_request_id,'resolve_trade',payload,
  jsonb_build_object('id',o.id,'thread_id',o.thread_id,'status',p_status));
END $$;

-- Explicit ACLs for every entry point, including reruns; private helpers are never API endpoints.
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure signature,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='cfc_runtime_private' OR (n.nspname='public' AND p.proname IN
  ('cfc_get_league_runtime','cfc_get_league_runtime_public','cfc_get_draft_log','cfc_refresh_runtime_snapshot','cfc_refresh_runtime_snapshot_system',
   'cfc_create_trade_offer','cfc_resolve_trade_offer','cfc_submit_draft_pick','cfc_draft_command','cfc_tick_due_draft')) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);
  IF f.nspname='public' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature); END IF;
 END LOOP;
END $$;
COMMIT;
